import React, { useState, useEffect } from "react";
import "./navbar.css";

export default function Navbar({ isLogin, onLogin, onLogout }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);

  const email = localStorage.getItem("email");
  const role = localStorage.getItem("role");
  const isAdmin = role === "admin";

  const [name, setName] = useState("");

  useEffect(() => {
    const storedName = localStorage.getItem("name");
    if (storedName) setName(storedName);
  }, []);

  const firstLetter = name ? name.trim().charAt(0).toUpperCase() : "U";

  const links = [
    { name: "Home", id: "homePage" },
    { name: "About Us", id: "About" },
    { name: "Contact", id: "contact" },
    { name: "Blog", id: "Blog" },
  ];

  return (
    <nav style={styles.navbar}>
      <a href="#homePage" style={styles.logo}>DailyCode</a>

      <ul style={{ ...styles.navLinks, ...(menuOpen ? styles.showMenu : {}) }}>
        {links.map((link, i) => (
          <li key={i}>
            <a href={`#${link.id}`} style={styles.link}>{link.name}</a>
          </li>
        ))}

        {!isLogin ? (
          <li>
            <span
              style={styles.link}
              onClick={() => {
                onLogin();
                setMenuOpen(false);
              }}
            >
              Login
            </span>
          </li>
        ) : (
          <li style={{ position: "relative" }}>
            <div
              style={styles.avatar}
              onClick={() => setProfileOpen(!profileOpen)}
            >
              {firstLetter}
            </div>

            {profileOpen && (
              <div style={styles.dropdown}>
                <p style={styles.profileName}>{name}</p>
                <p style={styles.profileEmail}>{email}</p>

                {/* 👑 ADMIN LINK */}
                {isAdmin && (
                  <a href="#admin" style={styles.adminLink}>
                    🛠 Admin Dashboard
                  </a>
                )}

                <hr style={{ margin: "10px 0", borderColor: "#334155" }} />

                <button
                  style={styles.logoutBtn}
                  onClick={() => {
                    setProfileOpen(false);
                    onLogout();
                  }}
                >
                  Logout
                </button>
              </div>
            )}
          </li>
        )}
      </ul>

      <button style={styles.menuBtn} onClick={() => setMenuOpen(!menuOpen)}>
        {menuOpen ? "✖" : "☰"}
      </button>
    </nav>
  );
}
